import math, statistics

# ------------------------------------------------------------
# Helper to parse the motion log of a scope into a dict
# ------------------------------------------------------------
def _parse_motion_log(scope: str):
    """Return dict mapping 'Object N' -> list of dicts {frame, x, y, vx, vy}."""
    node = node_by_title(doc, scope)
    if not node:
        return {}
    tbl = None
    for child in children(doc, node):
        if child.get("kind") == "table" and child.get("title", "").endswith(": Motion log"):
            tbl = child.get("table", {})
            break
    if not tbl:
        return {}
    rows = tbl.get("rows", [])
    logs: dict[str, list[dict]] = {}
    for r in rows:
        try:
            f = int(r[0])
            obj_desc = r[1].strip()  # e.g. "1 cyan rubber sphere"
            obj_id = f"Object {obj_desc.split()[0]}"
            x = float(r[2]); y = float(r[3]); vx = float(r[4]); vy = float(r[5])
            logs.setdefault(obj_id, []).append({"frame": f, "x": x, "y": y, "vx": vx, "vy": vy})
        except Exception:
            continue
    for lst in logs.values():
        lst.sort(key=lambda d: d["frame"])
    return logs

# ------------------------------------------------------------
# Helper to compute Euclidean distance between two state dicts
# ------------------------------------------------------------
def _dist(a, b):
    return math.hypot(a["x"] - b["x"], a["y"] - b["y"])

# ------------------------------------------------------------
# 1️⃣  Median collision distance
# ------------------------------------------------------------
collision_dists = []
for node in doc["nodes"]:
    if not node.get("title", "").startswith("Video "):
        continue
    scope = node["title"]
    logs = _parse_motion_log(scope)
    evs = observed_events(doc, scope)
    for ev in evs:
        t = int(ev["time"])
        recs = []
        for eid in ev["participants"]:
            # Find record at exact frame t
            rec = next((r for r in logs[eid] if r["frame"] == t), None)
            if rec is None:
                break
            recs.append(rec)
        if len(recs) == 2:
            collision_dists.append(_dist(recs[0], recs[1]))
median_dist = statistics.median(collision_dists) if collision_dists else None
print("Median collision distance:", median_dist)

# ------------------------------------------------------------
# 2️⃣  Average exponential friction rate k
# ------------------------------------------------------------
rates = []
for node in doc["nodes"]:
    if not node.get("title", "").startswith("Video "):
        continue
    logs = _parse_motion_log(node["title"])
    for lst in logs.values():
        for i in range(1, len(lst)):
            r0, r1 = lst[i-1], lst[i]
            dt = r1["frame"] - r0["frame"]
            if dt <= 0:
                continue
            v0 = math.hypot(r0["vx"], r0["vy"])
            v1 = math.hypot(r1["vx"], r1["vy"])
            if v0 == 0 or v1 == 0:
                continue
            k = -math.log(v1 / v0) / dt
            rates.append(k)
avg_k = statistics.mean(rates) if rates else None
print("Average friction decay rate k:", avg_k)

# ------------------------------------------------------------
# 3️⃣  90th percentile collision distance
# ------------------------------------------------------------
if collision_dists:
    collision_dists.sort()
    idx = int(len(collision_dists) * 0.9) - 1
    idx = max(0, idx)
    p90_dist = collision_dists[idx]
    print("90th percentile collision distance:", p90_dist)
else:
    print("90th percentile collision distance: None")

