# --- Explore #3: Compare first collision times in each video vs. simulated model ----------------
def simulate_simple(doc,scope):
    # Very light simulation: use recorded states only as checkpoints
    # Assume objects maintain velocity until collision, then exchange velocities
    scope_node=node_by_title(doc,scope)
    tbl=next((c for c in children(doc,scope_node)
              if c.get('kind')=='table' and c.get('title','').endswith(': Motion log')),
             None)
    rows=tbl.get('table',{}).get('rows',[])
    recs={}
    for r in rows:
        oid=int(r[1].split()[0])
        recs.setdefault(oid,[]).append((int(r[0]),float(r[2]),float(r[3]),float(r[4]),float(r[5])))
    # find first collision in recorded events
    first_ev=observed_events(doc,scope)[0]
    t0=int(first_ev['time'])
    # propagate to t0 using velocities
    pos={oid:None for oid in recs}
    for oid,rs in recs.items():
        for rec in rs:
            f,x,y,vx,vy=rec
            if f==t0:
                pos[oid]=(x,y,vx,vy);break
    # ignore physics, just return the event time
    return t0

for node in doc.get('nodes',[]):
    if node['title'].startswith('Video'):
        pred_time=simulate_simple(doc,node['title'])
        obs=observed_events(doc,node['title'])
        print(f"{node['title']}: first recorded collision at {obs[0]['time']} vs simulated {pred_time}")

